const ALLOWED_MIME_TYPES = new Set([
  'application/pdf',
  'image/jpeg',
  'image/png',
  'image/webp'
]);
const MAX_BYTES = 15 * 1024 * 1024; // 15 MB

const item = $input.first();
const binaryObj = item.binary || {};
const binaryKeys = Object.keys(binaryObj);

if (binaryKeys.length === 0) {
  throw new Error('No se recibió ningún archivo binario (PDF o imagen) en la solicitud.');
}

const binaryKey = binaryKeys[0];
const fileMeta = binaryObj[binaryKey];
const mimeType = fileMeta.mimeType || 'application/octet-stream';

if (!ALLOWED_MIME_TYPES.has(mimeType)) {
  throw new Error(`Tipo de archivo no soportado: ${mimeType}. Usa PDF, JPG, PNG o WEBP.`);
}

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
if (buffer.length > MAX_BYTES) {
  throw new Error(`El archivo excede el límite de 15 MB (${(buffer.length / 1024 / 1024).toFixed(2)} MB).`);
}

const base64Data = buffer.toString('base64');
const sourceFile = fileMeta.fileName || `comprobante-${Date.now()}`;

const systemInstruction = `Eres un auditor contable experto en extracción estructurada de comprobantes fiscales (facturas, recibos, tickets y boletas).
Tu tarea es leer el archivo adjunto (imagen o PDF) y extraer únicamente los datos visibles con máxima precisión.
Reglas estrictas:
1. NO inventes ni recalcules valores faltantes para forzar que las sumas cuadren: extrae exactamente los números impresos en el documento.
2. Convierte todas las fechas al formato ISO YYYY-MM-DD.
3. Normaliza la moneda al código ISO-4217 de 3 letras (USD, MXN, EUR, ARS, COP, CLP, PEN, BRL).
4. Usa números decimales puros con punto decimal (sin símbolos de moneda ni separadores de miles).
5. Si no existe descuento o propina, devuelve 0.
6. Si un campo de texto no aparece, devuelve cadena vacía "".
7. Asigna confianza_extraccion entre 0.0 y 1.0 reflejando la legibilidad real del documento.`;

const responseSchema = {
  type: 'OBJECT',
  properties: {
    proveedor: { type: 'STRING' },
    tax_id_proveedor: { type: 'STRING' },
    tipo_comprobante: {
      type: 'STRING',
      enum: ['factura', 'recibo', 'ticket', 'boleta', 'nota_credito', 'comprobante']
    },
    numero_comprobante: { type: 'STRING' },
    fecha_emision: { type: 'STRING' },
    moneda: { type: 'STRING' },
    subtotal: { type: 'NUMBER' },
    descuento: { type: 'NUMBER' },
    impuestos: { type: 'NUMBER' },
    propina: { type: 'NUMBER' },
    total: { type: 'NUMBER' },
    confianza_extraccion: { type: 'NUMBER' },
    items: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          descripcion: { type: 'STRING' },
          cantidad: { type: 'NUMBER' },
          precio_unitario: { type: 'NUMBER' },
          importe: { type: 'NUMBER' }
        },
        required: ['descripcion', 'importe']
      }
    }
  },
  required: [
    'proveedor',
    'tipo_comprobante',
    'fecha_emision',
    'moneda',
    'subtotal',
    'descuento',
    'impuestos',
    'propina',
    'total',
    'confianza_extraccion',
    'items'
  ]
};

return [
  {
    json: {
      source_file: sourceFile,
      mime_type: mimeType,
      file_size_bytes: buffer.length,
      gemini_request: {
        systemInstruction: {
          parts: [{ text: systemInstruction }]
        },
        contents: [
          {
            role: 'user',
            parts: [
              {
                text: 'Extrae todos los campos contables y el detalle de ítems de este comprobante siguiendo estrictamente el esquema JSON.'
              },
              {
                inlineData: {
                  mimeType,
                  data: base64Data
                }
              }
            ]
          }
        ],
        generationConfig: {
          temperature: 0,
          responseMimeType: 'application/json',
          responseSchema
        }
      }
    }
  }
];

const MATH_TOLERANCE = 0.02;
const MIN_CONFIDENCE = 0.8;
const MAX_TAX_RATE = 0.35;
const ALLOWED_CURRENCIES = new Set([
  'USD', 'EUR', 'MXN', 'ARS', 'COP', 'CLP', 'PEN', 'BRL', 'UYU', 'PYG',
  'BOB', 'CRC', 'DOP', 'GTQ', 'HNL', 'NIO', 'PAB', 'VES', 'GBP', 'CAD'
]);

const round2 = (v) => Math.round((Number(v) + Number.EPSILON) * 100) / 100;
const toFinite = (v, fb = null) => {
  if (v === null || v === undefined || v === '') return fb;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/,/g, '').trim());
  return Number.isFinite(n) ? n : fb;
};
const normalizeText = (v) => (typeof v === 'string' ? v.trim().replace(/\s+/g, ' ') : '');
const isValidIsoDate = (s) => {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const [y, m, d] = s.split('-').map(Number);
  const dt = new Date(Date.UTC(y, m - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d;
};

// Hash determinístico FNV-1a 64-bit hex (compatible con sandbox de n8n sin imports externos)
function fingerprintHash(input) {
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < input.length; i++) {
    const ch = input.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return ((h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0'));
}

const geminiResponse = $input.first().json;
const sourceFile = $('Preparar Archivo y Payload Gemini').first().json.source_file || '';
const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text || '';

let extracted = null;
const errors = [];
const warnings = [];

try {
  extracted = JSON.parse(rawText);
} catch (err) {
  errors.push({ code: 'INVALID_JSON', message: 'Gemini no devolvió un JSON parseable.' });
}

if (!extracted || typeof extracted !== 'object') {
  return [{
    json: {
      estado_validacion: 'REVISION_MANUAL',
      es_valida: false,
      errores: errors,
      advertencias: warnings,
      registro_sheets: {
        id_registro: `ERR-${Date.now()}`,
        fecha_procesamiento: new Date().toISOString(),
        estado_validacion: 'REVISION_MANUAL',
        proveedor: 'ERROR_PARSEO',
        errores_validacion: errors.map((e) => `[${e.code}] ${e.message}`).join(' | '),
        archivo_origen: sourceFile
      }
    }
  }];
}

const proveedor = normalizeText(extracted.proveedor);
const taxId = normalizeText(extracted.tax_id_proveedor || '');
const tipoComprobante = normalizeText(extracted.tipo_comprobante || 'comprobante').toLowerCase();
const numeroComprobante = normalizeText(extracted.numero_comprobante || '');
const fechaEmision = normalizeText(extracted.fecha_emision);
const moneda = normalizeText(extracted.moneda).toUpperCase();

const subtotal = toFinite(extracted.subtotal);
const descuento = toFinite(extracted.descuento, 0);
const impuestos = toFinite(extracted.impuestos, 0);
const propina = toFinite(extracted.propina, 0);
const totalExtraido = toFinite(extracted.total);
const confianza = toFinite(extracted.confianza_extraccion, 0);
const items = Array.isArray(extracted.items) ? extracted.items : [];

if (!proveedor) errors.push({ code: 'MISSING_VENDOR', message: 'Falta el nombre del proveedor.' });
if (!fechaEmision || !isValidIsoDate(fechaEmision)) {
  errors.push({ code: 'INVALID_DATE', message: `Fecha de emisión inválida ("${fechaEmision}").` });
} else {
  const parsedDate = new Date(`${fechaEmision}T00:00:00Z`);
  if (parsedDate > new Date(Date.now() + 86400000)) {
    errors.push({ code: 'FUTURE_DATE', message: `Fecha de emisión en el futuro (${fechaEmision}).` });
  }
}

if (!moneda || !/^[A-Z]{3}$/.test(moneda)) {
  errors.push({ code: 'INVALID_CURRENCY', message: `Moneda inválida ("${moneda}").` });
} else if (!ALLOWED_CURRENCIES.has(moneda)) {
  warnings.push({ code: 'UNCOMMON_CURRENCY', message: `Moneda poco común: ${moneda}.` });
}

if (subtotal === null || subtotal < 0) errors.push({ code: 'INVALID_SUBTOTAL', message: 'Subtotal inválido.' });
if (totalExtraido === null || totalExtraido < 0) errors.push({ code: 'INVALID_TOTAL', message: 'Total inválido.' });
if (descuento < 0 || impuestos < 0 || propina < 0) {
  errors.push({ code: 'NEGATIVE_COMPONENT', message: 'Descuento, impuestos y propina deben ser >= 0.' });
}

let totalCalculado = null;
let diferenciaMatematica = null;
if (subtotal !== null && totalExtraido !== null) {
  totalCalculado = round2(subtotal - descuento + impuestos + propina);
  diferenciaMatematica = round2(totalExtraido - totalCalculado);
  if (Math.abs(diferenciaMatematica) > MATH_TOLERANCE) {
    errors.push({
      code: 'MATH_TOTAL_MISMATCH',
      message: `Total extraído (${totalExtraido.toFixed(2)}) != calculado (${totalCalculado.toFixed(2)}), delta ${diferenciaMatematica.toFixed(2)} ${moneda}.`
    });
  }
}

let sumaItems = null;
if (items.length > 0) {
  let acumulado = 0;
  items.forEach((it, idx) => {
    const cant = toFinite(it?.cantidad);
    const pu = toFinite(it?.precio_unitario);
    const imp = toFinite(it?.importe);
    if (imp === null || imp < 0) {
      errors.push({ code: 'INVALID_LINE_ITEM', message: `Ítem #${idx + 1} sin importe válido.` });
      return;
    }
    acumulado += imp;
    if (cant !== null && pu !== null) {
      const esp = round2(cant * pu);
      if (Math.abs(esp - imp) > MATH_TOLERANCE) {
        errors.push({ code: 'LINE_ITEM_CALC_MISMATCH', message: `Ítem #${idx + 1}: ${cant}×${pu}=${esp.toFixed(2)} vs ${imp.toFixed(2)}.` });
      }
    }
  });
  sumaItems = round2(acumulado);
  const itemsTol = Math.min(0.05, Math.max(MATH_TOLERANCE, items.length * 0.01));
  if (subtotal !== null && Math.abs(sumaItems - subtotal) > itemsTol) {
    errors.push({ code: 'LINE_ITEMS_SUBTOTAL_MISMATCH', message: `Suma ítems (${sumaItems.toFixed(2)}) != subtotal (${subtotal.toFixed(2)}).` });
  }
}

let tasaImpuestoPct = 0;
if (subtotal !== null && subtotal - descuento > 0 && impuestos > 0) {
  const base = subtotal - descuento;
  tasaImpuestoPct = round2((impuestos / base) * 100);
  if (impuestos / base > MAX_TAX_RATE) {
    errors.push({ code: 'ABNORMAL_TAX_RATE', message: `Tasa impositiva sospechosa (${tasaImpuestoPct}%).` });
  }
}

if (confianza < MIN_CONFIDENCE) {
  errors.push({ code: 'LOW_CONFIDENCE', message: `Confianza baja (${(confianza * 100).toFixed(1)}%).` });
}

const esValida = errors.length === 0;
const estadoValidacion = esValida ? 'APROBADA' : 'REVISION_MANUAL';
const rawKey = [proveedor.toLowerCase(), numeroComprobante.toLowerCase(), fechaEmision, moneda, round2(totalExtraido ?? 0).toFixed(2)].join('|');
const fingerprint = fingerprintHash(rawKey);

const registroSheets = {
  id_registro: `INV-${fingerprint.toUpperCase()}`,
  fecha_procesamiento: new Date().toISOString(),
  estado_validacion: estadoValidacion,
  proveedor: proveedor || 'DESCONOCIDO',
  tax_id_proveedor: taxId,
  tipo_comprobante: tipoComprobante,
  numero_comprobante: numeroComprobante,
  fecha_emision: fechaEmision,
  moneda,
  subtotal: subtotal !== null ? round2(subtotal) : '',
  descuento: round2(descuento),
  impuestos: round2(impuestos),
  propina: round2(propina),
  total_extraido: totalExtraido !== null ? round2(totalExtraido) : '',
  total_calculado: totalCalculado !== null ? totalCalculado : '',
  diferencia_matematica: diferenciaMatematica !== null ? diferenciaMatematica : '',
  tasa_impuesto_pct: tasaImpuestoPct,
  confianza_ia: round2(confianza),
  cantidad_items: items.length,
  errores_validacion: errors.map((e) => `[${e.code}] ${e.message}`).join(' | '),
  advertencias: warnings.map((w) => `[${w.code}] ${w.message}`).join(' | '),
  fingerprint,
  archivo_origen: sourceFile
};

return [{
  json: {
    estado_validacion: estadoValidacion,
    es_valida: esValida,
    errores: errors,
    advertencias: warnings,
    metricas_matematicas: {
      subtotal,
      descuento,
      impuestos,
      propina,
      total_extraido: totalExtraido,
      total_calculado: totalCalculado,
      diferencia_matematica: diferenciaMatematica,
      suma_items: sumaItems,
      tasa_impuesto_pct: tasaImpuestoPct
    },
    registro_sheets: registroSheets
  }
}];
